// wf.kb.ingest > "Plan"
// Input: the job row with its input, the kb.* settings, the embedding models
// and the sources selected for this job (SQL "Start job").
// Output: one item per source for the loop, or one item {empty: true}.
const row = $input.first().json;
if (!row.job_id) return [{ json: { empty: true, job_id: null, reason: 'job_not_found_or_finished' } }];
const cfg = {};
for (const [k, v] of Object.entries(row.cfg || {})) cfg[k.replace(/^kb\./, '')] = v;
cfg.ollama_base_url = (row.cfg || {})['ollama.base_url'] || 'http://ollama:11434';
const wanted = cfg.embedding_models || ['bge-m3', 'multilingual-e5-large'];
const models = (row.models || []).filter((m) => wanted.includes(m.name));
const missing = wanted.filter((n) => !models.some((m) => m.name === n));
if (missing.length) return [{ json: { empty: true, job_id: row.job_id, reason: 'unknown_models: ' + missing.join(',') } }];
const sources = row.sources || [];
const requested = (row.input && row.input.sources) || [];
const unknown = requested.filter((k) => !sources.some((s) => s.source_key === k));
if (!sources.length) return [{ json: { empty: true, job_id: row.job_id, reason: 'no_sources', unknown_sources: unknown } }];
return sources.map((s) => ({ json: {
  job_id: row.job_id, force: !!(row.input && row.input.force), cfg, models,
  source: {
    id: s.id, source_key: s.source_key, url: s.url, language: s.language, cite_as: s.cite_as,
    jurisdiction_code: s.jurisdiction_code, fetch: s.fetch_config || {},
  },
  unknown_sources: unknown,
} }));

// Worker workflows (wf.kb.ingest, wf.eval.retrieval) > "Job failed"
// Error output of any step after "Start job": the job ends as failed with the
// (redacted) error text, so it never stays "running" after a handled failure.
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const start = $('Start job').first().json;
const msg = redactPg(errorText($input.first().json)).slice(0, 500) || 'worker step failed without a message';
return [{ json: { job_id: start.job_id, status: 'failed', error: msg, output: { failed_step: true } } }];

// wf.kb.ingest > "Normalize result"
// Input: the outcome of wf.kb.ingest_source for the current source, or the
// error item when that workflow failed (Execute Workflow continues on error).
const cur = $('Loop sources').first().json;
const r = $input.first().json || {};
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

let out;
if (r.status === 'ok' || r.status === 'skipped') {
  out = { ...r };
} else {
  out = {
    job_id: cur.job_id, source_id: cur.source.id, source_key: cur.source.source_key,
    status: 'failed', step: 'source_workflow', action: null,
    error: redactPg(errorText(r)).slice(0, 500) || 'source workflow failed without a message',
    detail: {}, ms: null,
  };
}
out.log = [cur.job_id, cur.source.id, cur.source.source_key, out.step || 'done', out.status,
  JSON.stringify({ action: out.action || null, chunks: out.chunks || null, embeddings: out.embeddings || null,
                   error: out.error || null, ...(out.detail || {}) }),
  out.ms == null ? null : Math.round(out.ms), out.status === 'failed' ? out.error : null];
return [{ json: out }];

// wf.kb.ingest > "Summarize"
// Input: one result per source from wf.kb.ingest_source (the loop's "done"
// output), or the {empty} item from "Plan". Output: the job's final state.
const items = $input.all().map((i) => i.json);
const plan = $('Plan').first().json;
if (plan.empty) {
  return [{ json: { job_id: plan.job_id, status: 'failed', error: plan.reason,
                    output: { sources: [], unknown_sources: plan.unknown_sources || [] } } }];
}
const results = items.map((r) => ({
  source_key: r.source_key || (r.source && r.source.source_key) || null,
  status: r.status || 'failed',
  step: r.step || null,
  action: r.action || null,
  error: r.status === 'ok' || r.status === 'skipped' ? null : (r.error || errorOf(r)),
  reason: r.status !== 'skipped' ? null : r.step === 'robots' && r.detail && r.detail.robots
    ? r.detail.robots.reason + (r.detail.robots.rule ? ` (${r.detail.robots.rule})` : '') + ` [robots.txt HTTP ${r.detail.robots.status}]`
      + (r.detail.robots.error ? ` ${r.detail.robots.error}` : '')
    : r.step,
  chunks: r.chunks || null,
  embeddings: r.embeddings || null,
  ms: r.ms || null,
}));
function errorOf(r) {
  const e = r.error;
  if (!e) return 'no result from the source workflow';
  return typeof e === 'string' ? e : (e.message || JSON.stringify(e)).slice(0, 300);
}
const failed = results.filter((r) => r.status === 'failed');
const counts = { ok: 0, skipped: 0, failed: 0 };
for (const r of results) counts[r.status] = (counts[r.status] || 0) + 1;
// Every robots.txt request failed without any HTTP answer: that is our network, not
// the sites. Skipping is still right per source (RFC 9309), but the job must not
// report success (T-25).
const offline = items.filter((r) => r.status === 'skipped' && r.step === 'robots' && r.detail && r.detail.robots
                                    && r.detail.robots.status === 0);
const noNetwork = results.length >= 2 && offline.length === results.length;
const firstErr = noNetwork ? (offline[0].detail.robots.error || 'no error message') : null;
return [{ json: {
  job_id: plan.job_id,
  status: failed.length || noNetwork ? 'failed' : 'succeeded',
  error: noNetwork ? `no_network: robots.txt unreachable for all ${results.length} sources (${firstErr})`
    : failed.length ? `${failed.length} of ${results.length} sources failed` : null,
  output: { counts, sources: results, unknown_sources: plan.unknown_sources || [] },
} }];
